class _PigeonCodec extends StandardMessageCodec {
  const _PigeonCodec();
  @override
  void writeValue(WriteBuffer buffer, Object? value) {
    if (value is int) {
      buffer.putUint8(4);
      buffer.putInt64(value);
    }    else if (value is ClientOptionsMessage) {
      buffer.putUint8(129);
      writeValue(buffer, value.encode());
    }    else if (value is BackendMessage) {
      buffer.putUint8(130);
      writeValue(buffer, value.encode());
    }    else if (value is TokensMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.encode());
    }    else if (value is ClipMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.encode());
    }    else if (value is CalibrationMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.encode());
    }    else if (value is ModelMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.encode());
    }    else if (value is SessionOptionsMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.encode());
    }    else if (value is HeadMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.encode());
    }    else if (value is DecodedMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.encode());
    }    else if (value is ChunkMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.encode());
    }    else if (value is ErrorMessage) {
      buffer.putUint8(139);
      writeValue(buffer, value.encode());
    }    else if (value is EventMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.encode());
    }    else if (value is HeadsMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.encode());
    }    else if (value is StoredModelMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.encode());
    }    else if (value is StorageMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.encode());
    }    else if (value is UnitsMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    }    else if (value is SharingStateMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    }    else if (value is SharingItemMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
    }    else if (value is SharingSummaryMessage) {
      buffer.putUint8(147);
      writeValue(buffer, value.encode());
    }    else if (value is RecitedOutcomeMessage) {
      buffer.putUint8(148);
      writeValue(buffer, value.encode());
    }    else if (value is SharingThemeMessage) {
      buffer.putUint8(149);
      writeValue(buffer, value.encode());
    }    else if (value is ChunkUpdate) {
      buffer.putUint8(150);
      writeValue(buffer, value.encode());
    }    else if (value is EventUpdate) {
      buffer.putUint8(151);
      writeValue(buffer, value.encode());
    }    else if (value is ClosedUpdate) {
      buffer.putUint8(152);
      writeValue(buffer, value.encode());
    }    else if (value is ProgressUpdate) {
      buffer.putUint8(153);
      writeValue(buffer, value.encode());
    } else {
      super.writeValue(buffer, value);
    }
  }

  @override
  Object? readValueOfType(int type, ReadBuffer buffer) {
    switch (type) {
      case 129:
        return ClientOptionsMessage.decode(readValue(buffer)!);
      case 130:
        return BackendMessage.decode(readValue(buffer)!);
      case 131:
        return TokensMessage.decode(readValue(buffer)!);
      case 132:
        return ClipMessage.decode(readValue(buffer)!);
      case 133:
