Stream<UpdateMessage> updates( {String instanceName = ''}) {
  if (instanceName.isNotEmpty) {
    instanceName = '.$instanceName';
  }
  final EventChannel updatesChannel =
      EventChannel('dev.flutter.pigeon.quranlab_tajweedformer.TajweedEventApi.updates$instanceName', pigeonMethodCodec);
  return updatesChannel.receiveBroadcastStream().map((dynamic event) {
    return event as UpdateMessage;
  });
}
    
